import { useEffect, useMemo, useRef, useState } from 'react';
import JsBarcode from 'jsbarcode';
import { Search, Plus, Pencil, History, X, AlertTriangle, Printer, Barcode, Image as ImageIcon, CalendarClock, ChevronDown, Trash2, Package, Pill, DollarSign, Info } from 'lucide-react';
import type { InventoryLot, InventoryMovement, LotKardexMovement, Product, Supplier } from '../domain/types';
import { InventoryLotsKardex } from './InventoryLotsKardex';

const productDisplayName = (product: Product) => product.laboratory?.trim() ? `${product.name} — ${product.laboratory.trim()}` : product.name;
const money = (value: number) => new Intl.NumberFormat('es-HN', { style: 'currency', currency: 'HNL', maximumFractionDigits: 2 }).format(value);
const margin = (price: number, cost: number) => price > 0 ? ((price - cost) / price) * 100 : 0;
const daysUntil = (expiry: string) => {
  if (!expiry) return Number.POSITIVE_INFINITY;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return Math.ceil((new Date(expiry + 'T00:00:00').getTime() - today.getTime()) / 86400000);
};
const inferPackageUnits = (presentation:string) => {
  const match=presentation.match(/(?:x|×)\s*(\d+)/i)||presentation.match(/(\d+)\s*(?:tabletas?|cápsulas?|capsulas?|unidades?|ml|g|mg)\b/i);
  return match?Math.max(1,Number(match[1])):1;
};
const inferBaseUnit = (presentation:string) => {
  const match=presentation.match(/(?:tabletas?|cápsulas?|capsulas?|unidades?|ml|g|mg)\b/i);
  return match?match[0].toLowerCase().replace(/s$/,''):'unidad';
};
const makeBarcode = (products: Product[]) => {
  const existing = new Set(products.map(p => p.code.trim().toUpperCase()).filter(Boolean));
  let code = '';
  do { code = `DF${Date.now().toString(36).toUpperCase()}${Math.random().toString(36).slice(2, 5).toUpperCase()}`; }
  while (existing.has(code));
  return code;
};

export function Inventory({products, allProducts, search, setSearch, movements, lots, lotKardex, fefoProductIds, onAddOpeningLot, onActivateFefo, onAdjustLot, onFraction, onNew, onEdit}:{products:Product[];allProducts:Product[];search:string;setSearch:(v:string)=>void;movements:InventoryMovement[];lots:InventoryLot[];lotKardex:LotKardexMovement[];fefoProductIds:number[];onAddOpeningLot:(productId:number,lotCode:string,expiry:string,quantity:number,unitCost:number,supplier:string)=>boolean;onActivateFefo:(productId:number)=>boolean;onAdjustLot:(lotId:string,delta:number,note:string)=>boolean;onFraction:(sourceId:number,packageQuantity:number,unitsPerPackage:number,presentationName:string,unitsPerPresentation:number,baseUnitName:string)=>boolean;onNew:()=>void;onEdit:(p:Product)=>void}) {
  const lowStock = products.filter(p => p.itemType !== 'Servicio' && p.stock <= p.minStock);
  const usesLotExpiry = (p: Product) => fefoProductIds.includes(p.id);
  const productLotsForExpiry = (p: Product) => lots.filter(lot => lot.productId === p.id && lot.quantityRemaining > 0);
  const productExpiryDays = (p: Product) => {
    if (usesLotExpiry(p)) {
      const activeLots = productLotsForExpiry(p);
      const validDays = activeLots.map(lot => daysUntil(lot.expiry)).filter(Number.isFinite);
      return validDays.length ? Math.min(...validDays) : Number.POSITIVE_INFINITY;
    }
    return daysUntil(p.expiry);
  };
  const hasMissingLotExpiry = (p: Product) => usesLotExpiry(p) ? productLotsForExpiry(p).length === 0 || productLotsForExpiry(p).some(lot => !lot.expiry || !Number.isFinite(daysUntil(lot.expiry))) : !p.expiry || !Number.isFinite(daysUntil(p.expiry));
  const hasExpiredLot = (p: Product) => usesLotExpiry(p)
    ? productLotsForExpiry(p).some(lot => daysUntil(lot.expiry) < 0)
    : daysUntil(p.expiry) < 0;
  const hasExpiringLot = (p: Product, limit: number) => usesLotExpiry(p)
    ? productLotsForExpiry(p).some(lot => daysUntil(lot.expiry) >= 0 && daysUntil(lot.expiry) <= limit)
    : daysUntil(p.expiry) >= 0 && daysUntil(p.expiry) <= limit;
  const expiring = products.filter(p => hasExpiringLot(p, 90));
  const expired = products.filter(hasExpiredLot);
  const lowMargin = products.filter(p => margin(p.retail, p.cost) < 15);
  const [inventoryView, setInventoryView] = useState<'products'|'lots'|'kardex'>('products');
  const [expiryFilter, setExpiryFilter] = useState<'all'|'expired'|'30'|'60'|'90'|'180'|'missing'>('all');
  const [showExpiryControl, setShowExpiryControl] = useState(false);
  const [showMovementHistory, setShowMovementHistory] = useState(false);
  const movementToday = new Date().toLocaleDateString('en-CA');
  const [movementFrom, setMovementFrom] = useState(()=>movementToday.slice(0,8)+'01');
  const [movementTo, setMovementTo] = useState(movementToday);
  const [movementSearch, setMovementSearch] = useState('');
  const [movementPage, setMovementPage] = useState(1);
  const movementPageSize = 15;
  const [selected, setSelected] = useState<number[]>([]);
  const [detailProduct, setDetailProduct] = useState<Product | null>(null);
  const [fractionProduct,setFractionProduct]=useState<Product|null>(null);
  const detailClickTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [labelsOpen, setLabelsOpen] = useState(false);
  const [labelSearch, setLabelSearch] = useState('');
  const selectedProducts = useMemo(() => products.filter(p => selected.includes(p.id) && p.code.trim()), [products, selected]);
  const expiryDays = (p:Product) => productExpiryDays(p);
  const labelProducts = useMemo(() => products.filter(p => (p.name+' '+p.laboratory+' '+p.code+' '+p.category+' '+p.presentation).toLowerCase().includes(labelSearch.trim().toLowerCase())), [products, labelSearch]);
  const selectLabelVisible = (checked:boolean) => setSelected(current => checked ? [...new Set([...current,...labelProducts.map(p=>p.id)])] : current.filter(id => !labelProducts.some(p=>p.id===id)));
  const missingExpiry = products.filter(hasMissingLotExpiry);
  const expiredValue = products.reduce((sum,p)=>sum+(usesLotExpiry(p) ? productLotsForExpiry(p).filter(lot=>daysUntil(lot.expiry)<0).reduce((value,lot)=>value+Math.max(0,lot.quantityRemaining)*Math.max(0,lot.unitCost),0) : (daysUntil(p.expiry)<0 ? Math.max(0,p.stock)*Math.max(0,p.cost) : 0)),0);
  const upcomingValue = products.reduce((sum,p)=>sum+(usesLotExpiry(p) ? productLotsForExpiry(p).filter(lot=>daysUntil(lot.expiry)>=0&&daysUntil(lot.expiry)<=180).reduce((value,lot)=>value+Math.max(0,lot.quantityRemaining)*Math.max(0,lot.unitCost),0) : (daysUntil(p.expiry)>=0&&daysUntil(p.expiry)<=180 ? Math.max(0,p.stock)*Math.max(0,p.cost) : 0)),0);
  const visibleProducts = products.filter(p => {
    if(expiryFilter==='all') return true;
    if(expiryFilter==='missing') return hasMissingLotExpiry(p);
    if(expiryFilter==='expired') return hasExpiredLot(p);
    return hasExpiringLot(p, Number(expiryFilter));
  });
  const toggle = (id:number, checked:boolean) => setSelected(current => checked ? [...new Set([...current,id])] : current.filter(x => x !== id));
  const selectVisible = (checked:boolean) => setSelected(current => checked ? [...new Set([...current,...visibleProducts.map(p=>p.id)])] : current.filter(id => !visibleProducts.some(p=>p.id===id)));
  const filteredMovements = useMemo(() => movements.filter(m => { const date=String(m.date).slice(0,10); const query=movementSearch.trim().toLocaleLowerCase('es-HN'); return (!movementFrom||date>=movementFrom)&&(!movementTo||date<=movementTo)&&(!query||(m.productName+' '+m.type).toLocaleLowerCase('es-HN').includes(query)); }).sort((a,b)=>String(b.date).localeCompare(String(a.date))), [movements,movementFrom,movementTo,movementSearch]);
  const movementPageCount = Math.max(1,Math.ceil(filteredMovements.length/movementPageSize));
  const visibleMovements = filteredMovements.slice((movementPage-1)*movementPageSize,movementPage*movementPageSize);
  return <div className="content inventory-page">
    <div className="page-head inventory-page-head-compact"><div className="inventory-actions"><button className="secondary" onClick={()=>setLabelsOpen(true)} disabled={selected.length===0}><Printer size={17}/> Imprimir etiquetas ({selected.length})</button><button className="primary" onClick={onNew}><Plus size={17}/> Nuevo producto</button></div></div>
    <div className="inventory-view-switch"><label htmlFor="inventory-section-select">Sección de inventario</label><select id="inventory-section-select" value={inventoryView} onChange={e=>setInventoryView(e.target.value as 'products'|'lots'|'kardex')}><option value="products">Productos</option><option value="lots">Lotes</option><option value="kardex">Kardex FEFO</option></select></div>
    {inventoryView==='products' && <>
    <div className="inventory-toolbar card"><div className="search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por código, producto, categoría..." /></div><span className="count">{products.length} productos</span></div>
    <div className="inventory-alerts">
      {lowStock.length > 0 && <div className="card alert-card"><AlertTriangle size={18}/><div><strong>{lowStock.length} con stock bajo</strong><small>{lowStock.slice(0,3).map(p=>p.name).join(', ')}</small></div></div>}
      {expired.length > 0 && <div className="card alert-card danger"><AlertTriangle size={18}/><div><strong>{expired.length} vencido(s)</strong><small>{expired.slice(0,3).map(p=>p.name).join(', ')}</small></div></div>}
      {expiring.length > 0 && <div className="card alert-card"><AlertTriangle size={18}/><div><strong>{expiring.length} vence(n) en 90 días</strong><small>{expiring.slice(0,3).map(p=>p.name).join(', ')}</small></div></div>}
      {lowMargin.length > 0 && <div className="card alert-card"><AlertTriangle size={18}/><div><strong>{lowMargin.length} con margen minorista menor a 15%</strong><small>Revisa precio o costo antes de modificarlo.</small></div></div>}
    </div>
    <div className="card table-wrap inventory-products-card"><div className="card-title"><div><h3>Productos en inventario</h3><p>{visibleProducts.length} producto(s) · {expiryFilter==='all'?'Todos los vencimientos':expiryFilter==='expired'?'Solo vencidos':expiryFilter==='missing'?'Sin fecha registrada':`Próximos ${expiryFilter} días`}.</p></div><CalendarClock size={20}/></div><table className="inventory-products-table"><thead><tr><th><input aria-label="Seleccionar todos los productos visibles" type="checkbox" checked={visibleProducts.length>0&&visibleProducts.every(p=>selected.includes(p.id))} onChange={e=>selectVisible(e.target.checked)}/></th><th>Producto</th><th>Costo</th><th>Minorista</th><th>Mayorista</th><th>Stock</th><th>Vencimiento</th><th></th></tr></thead><tbody>{visibleProducts.map(p=><tr key={p.id} className="inventory-product-row" tabIndex={0} role="button" aria-label={"Ver información de "+productDisplayName(p)} title="Haz clic para ver la información del producto" onClick={e=>{if((e.target as HTMLElement).closest("button,input,select,a,label"))return;if(detailClickTimer.current)clearTimeout(detailClickTimer.current);detailClickTimer.current=setTimeout(()=>setDetailProduct(p),260);}} onDoubleClick={e=>{if((e.target as HTMLElement).closest("button,input,select,a,label"))return;if(detailClickTimer.current)clearTimeout(detailClickTimer.current);detailClickTimer.current=null;onEdit(p);}} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();setDetailProduct(p);}}}><td onClick={e=>e.stopPropagation()}><input aria-label={"Seleccionar "+p.name} type="checkbox" checked={selected.includes(p.id)} onChange={e=>toggle(p.id,e.target.checked)}/></td><td><div className="product-cell">{p.imageUrl&&<img src={p.imageUrl} alt="" loading="lazy"/>}<div><strong>{productDisplayName(p)}</strong><small>{p.code||'Sin código'} · {p.presentation} · {p.category}</small></div></div></td><td>{money(p.cost)}</td><td>{money(p.retail)}</td><td>{money(p.wholesale)}</td><td><span className={p.stock<=p.minStock?'stock low':'stock'}>{p.stock}{p.unitInventoryEnabled?' '+(p.baseUnitName||'unidades'):''}</span><small>Mín. {p.minStock}{p.unitInventoryEnabled?' '+(p.baseUnitName||'unidades'):''}</small></td><td><span className={hasExpiredLot(p)?'stock low':hasExpiringLot(p,90)?'stock low':'stock'}>{usesLotExpiry(p) ? (productLotsForExpiry(p).length ? (productLotsForExpiry(p).length===1 ? new Date(productLotsForExpiry(p)[0].expiry+'T00:00:00').toLocaleDateString('es-HN') : 'Varios lotes') : 'Sin lotes activos') : (p.expiry?new Date(p.expiry+'T00:00:00').toLocaleDateString('es-HN'):'Sin fecha')}</span></td><td onClick={e=>e.stopPropagation()}><div className="inventory-row-actions"><button type="button" className="inventory-fraction-btn" title={fefoProductIds.includes(p.id)?"Desactiva FEFO antes de fraccionar":"Fraccionar producto"} aria-label={"Fraccionar "+p.name} disabled={fefoProductIds.includes(p.id)||p.itemType==="Servicio"||p.stock<1} onClick={()=>setFractionProduct(p)}><Package size={15}/><span>Fraccionar</span></button><button className="icon-btn" title="Editar" aria-label={"Editar "+p.name} onClick={()=>onEdit(p)}><Pencil size={16}/></button></div></td></tr>)}</tbody></table></div>


    <section className="inventory-utility-section">
      <button type="button" className="inventory-utility-toggle" aria-expanded={showExpiryControl} onClick={()=>setShowExpiryControl(value=>!value)}>
        <span><CalendarClock size={18}/><span><strong>Control de vencimientos</strong><small>Filtros, productos próximos a vencer y valor comprometido</small></span></span><span className="inventory-utility-toggle-end"><small>{products.length} productos</small><ChevronDown size={18} className={showExpiryControl?'is-open':''}/></span>
      </button>
      {showExpiryControl && <div className="inventory-utility-content">    <section className="card expiry-control-panel">
      <div className="expiry-control-heading"><div><h3>Control de vencimientos</h3><p>Filtra los productos por fecha y revisa el valor de inventario comprometido. Cuando FEFO está activo, los importes y alertas se calculan con la cantidad disponible y el costo de cada lote.</p></div><CalendarClock size={20}/></div>
      <div className="expiry-summary">
        <div><small>Valor al costo vencido</small><strong>{money(expiredValue)}</strong><span>{expired.length} producto(s)</span></div>
        <div><small>Valor al costo que vence en 180 días</small><strong>{money(upcomingValue)}</strong><span>{products.filter(p=>hasExpiringLot(p,180)).length} producto(s)</span></div>
        <div><small>Sin vencimiento registrado</small><strong>{missingExpiry.length}</strong><span>Revisar ficha del producto</span></div>
      </div>
      <div className="expiry-filter-row" aria-label="Filtrar inventario por vencimiento">
        {([{id:'all',label:'Todos'},{id:'expired',label:'Vencidos'},{id:'30',label:'Próximos 30 días'},{id:'60',label:'Próximos 60 días'},{id:'90',label:'Próximos 90 días'},{id:'180',label:'Próximos 180 días'},{id:'missing',label:'Sin fecha'}] as const).map(option=><button key={option.id} className={expiryFilter===option.id?'primary':'secondary'} onClick={()=>setExpiryFilter(option.id)}>{option.label}</button>)}
      </div>
    </section></div>}
    </section>
    <section className="inventory-utility-section">
      <button type="button" className="inventory-utility-toggle" aria-expanded={showMovementHistory} onClick={()=>setShowMovementHistory(value=>!value)}>
        <span><History size={18}/><span><strong>Historial de movimientos</strong><small>Consulta entradas y salidas recientes del inventario</small></span></span><span className="inventory-utility-toggle-end"><small>{movements.length} registros</small><ChevronDown size={18} className={showMovementHistory?'is-open':''}/></span>
      </button>
      {showMovementHistory && <div className="inventory-utility-content"><div className="card table-wrap"><div className="card-title"><div><h3>Historial de movimientos</h3><p>{filteredMovements.length} movimiento(s) encontrados · mostrando {movementPageSize} por página.</p></div><History size={20}/></div><div className="inventory-movement-filters"><label>Desde<input type="date" value={movementFrom} max={movementTo||undefined} onChange={e=>{setMovementFrom(e.target.value);setMovementPage(1);}}/></label><label>Hasta<input type="date" value={movementTo} min={movementFrom||undefined} onChange={e=>{setMovementTo(e.target.value);setMovementPage(1);}}/></label><label className="inventory-movement-search">Buscar producto o tipo<input type="search" value={movementSearch} onChange={e=>{setMovementSearch(e.target.value);setMovementPage(1);}} placeholder="Nombre del producto o movimiento"/></label><button type="button" className="secondary" onClick={()=>{setMovementFrom('');setMovementTo('');setMovementSearch('');setMovementPage(1);}}>Todo el historial</button><button type="button" className="secondary" onClick={()=>{const today=new Date().toLocaleDateString('en-CA');setMovementFrom(today.slice(0,8)+'01');setMovementTo(today);setMovementSearch('');setMovementPage(1);}}>Este mes</button></div><div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Stock antes</th><th>Stock después</th><th>Costo unitario</th></tr></thead><tbody>{visibleMovements.map(m=><tr key={m.id}><td>{new Date(m.date).toLocaleString('es-HN')}</td><td><strong>{m.productName}</strong></td><td>{m.type}</td><td>{m.quantity}</td><td>{m.stockBefore}</td><td>{m.stockAfter}</td><td>{money(m.unitCost)}</td></tr>)}{filteredMovements.length===0&&<tr><td colSpan={7}>No hay movimientos para los filtros seleccionados.</td></tr>}</tbody></table></div>{filteredMovements.length>0&&<div className="inventory-movement-pagination"><span>{(movementPage-1)*movementPageSize+1}–{Math.min(movementPage*movementPageSize,filteredMovements.length)} de {filteredMovements.length}</span><div><button type="button" className="secondary" disabled={movementPage<=1} onClick={()=>setMovementPage(page=>Math.max(1,page-1))}>Anterior</button><span>Página {movementPage} de {movementPageCount}</span><button type="button" className="secondary" disabled={movementPage>=movementPageCount} onClick={()=>setMovementPage(page=>Math.min(movementPageCount,page+1))}>Siguiente</button></div></div>}</div></div>}
    </section>


    </>}
    {inventoryView!=='products' && <InventoryLotsKardex view={inventoryView} products={allProducts} lots={lots} kardex={lotKardex} fefoProductIds={fefoProductIds} onAddOpeningLot={onAddOpeningLot} onActivate={onActivateFefo} onAdjustLot={onAdjustLot}/>}
    {fractionProduct&&<FractionInventoryModal product={fractionProduct} onClose={()=>setFractionProduct(null)} onConfirm={(packageQuantity,unitsPerPackage,presentationName,unitsPerPresentation,baseUnitName)=>{const ok=onFraction(fractionProduct.id,packageQuantity,unitsPerPackage,presentationName,unitsPerPresentation,baseUnitName);if(ok)setFractionProduct(null);return ok;}}/>}
    {detailProduct && !labelsOpen && <InventoryProductDetails product={detailProduct} onClose={()=>setDetailProduct(null)} onPrintLabel={(p)=>{setSelected([p.id]);setLabelsOpen(true);}} onEdit={(p)=>{setDetailProduct(null);onEdit(p);}}/>}
    {labelsOpen && <div className="modal-backdrop label-backdrop"><div className="modal labels-modal" style={{width:"min(1180px, calc(100vw - 32px))",maxWidth:"1180px",maxHeight:"calc(100vh - 32px)",overflowY:"auto",boxSizing:"border-box"}}><div className="modal-head no-print"><div><h2>Selección múltiple de productos</h2><p>Marca los productos que deseas incluir en las etiquetas. Puedes buscar y cambiar la selección aquí.</p></div><button className="icon-btn" aria-label="Cerrar ventana" onClick={()=>setLabelsOpen(false)}><X/></button></div>
      <div className="label-picker no-print" style={{display:"grid",gridTemplateColumns:"minmax(0, 1fr) minmax(260px, 0.9fr)",gap:16,alignItems:"start",minWidth:0}}>
        <div className="label-picker-toolbar" style={{gridColumn:"1 / -1",display:"flex",gap:12,alignItems:"center",minWidth:0,flexWrap:"wrap"}}><div className="search label-picker-search" style={{flex:"1 1 280px",minWidth:0,width:"100%",boxSizing:"border-box"}}><Search size={17}/><input value={labelSearch} onChange={e=>setLabelSearch(e.target.value)} placeholder="Buscar por nombre, código o categoría..." aria-label="Buscar productos para etiquetas"/></div><span className="count">{selected.length} seleccionado(s)</span></div>
        <div className="label-picker-bulk" style={{display:"flex",flexDirection:"column",alignItems:"stretch",gap:12,minWidth:0}}><label><input type="checkbox" checked={labelProducts.length>0&&labelProducts.every(p=>selected.includes(p.id))} onChange={e=>selectLabelVisible(e.target.checked)}/> Seleccionar todos los resultados ({labelProducts.length})</label><button type="button" className="secondary" onClick={()=>setSelected([])} disabled={selected.length===0}>Limpiar selección</button></div>
        <div className="label-picker-list" style={{minWidth:0,width:"100%",maxHeight:"340px",overflowY:"auto",overflowX:"hidden",boxSizing:"border-box"}}>{labelProducts.map(p=><label key={p.id} className={selected.includes(p.id)?'label-picker-item is-selected':'label-picker-item'}><input type="checkbox" checked={selected.includes(p.id)} onChange={e=>toggle(p.id,e.target.checked)}/>{p.imageUrl?<img src={p.imageUrl} alt="" loading="lazy"/>:<span className="label-picker-placeholder"><Barcode size={18}/></span>}<span className="label-picker-details" style={{minWidth:0,flex:"1 1 auto",overflowWrap:"anywhere",wordBreak:"normal"}}><strong>{productDisplayName(p)}</strong><small>{p.code||'Sin código'} · {p.presentation||p.category}</small></span><span className="label-picker-price">{money(p.retail)}</span></label>)}{labelProducts.length===0&&<p className="label-picker-empty">No se encontraron productos con esa búsqueda.</p>}</div>
        <p className="label-picker-note" style={{minWidth:0,margin:0,overflowWrap:"anywhere"}}>{selectedProducts.length} producto(s) seleccionado(s) con código listo para imprimir. Los productos sin código necesitan que se les asigne uno antes de generar etiquetas.</p>
      </div>
      {selectedProducts.length>0 ? <div className="print-labels" style={{display:"grid",gridTemplateColumns:"repeat(auto-fit, minmax(240px, 1fr))",gap:12,minWidth:0,marginTop:16}}>{selectedProducts.map(p=><BarcodeLabel key={p.id} product={p}/>)}</div> : <div className="form-error no-print">Selecciona al menos un producto que tenga código de barras para preparar las etiquetas.</div>}
      <div className="modal-actions no-print"><button className="secondary" onClick={()=>setLabelsOpen(false)}>Cerrar</button><button className="primary" disabled={selectedProducts.length===0} onClick={()=>window.print()}><Printer size={16}/> Imprimir {selectedProducts.length} etiqueta(s)</button></div></div></div>}
  </div>;
}


function FractionInventoryModal({product,onClose,onConfirm}:{product:Product;onClose:()=>void;onConfirm:(packageQuantity:number,unitsPerPackage:number,presentationName:string,unitsPerPresentation:number,baseUnitName:string)=>boolean}) {
  const inferredUnits=inferPackageUnits(product.presentation);
  const [packageQuantity,setPackageQuantity]=useState('1');
  const [unitsPerPackage,setUnitsPerPackage]=useState(String(inferredUnits));
  const [presentationName,setPresentationName]=useState('Blíster');
  const [unitsPerPresentation,setUnitsPerPresentation]=useState('10');
  const [baseUnitName,setBaseUnitName]=useState(inferBaseUnit(product.presentation));
  const [error,setError]=useState('');
  const packages=Number(packageQuantity),content=Number(unitsPerPackage),perPresentation=Number(unitsPerPresentation);
  const totalUnits=packages*content;
  const output=totalUnits/perPresentation;
  const unitCost=content>0?product.cost/content*perPresentation:0;
  const canConfirm=Number.isInteger(packages)&&packages>0&&packages<=product.stock&&Number.isInteger(content)&&content>0&&Number.isInteger(perPresentation)&&perPresentation>0&&Boolean(presentationName.trim())&&Boolean(baseUnitName.trim())&&Number.isInteger(output)&&output>0;
  const submit=()=>{setError('');if(!canConfirm){setError('Revisa las cantidades. El contenido debe dividirse exactamente entre las presentaciones que deseas crear.');return;}if(!onConfirm(packages,content,presentationName,perPresentation,baseUnitName))setError('No se pudo completar el fraccionamiento. Verifica la sincronización y la existencia disponible.');};
  return <div className="modal-backdrop fraction-modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}>
    <section className="modal fraction-modal" role="dialog" aria-modal="true" aria-labelledby="fraction-modal-title">
      <div className="modal-head"><div><h2 id="fraction-modal-title">Fraccionar producto</h2><p>Convierte existencias del empaque original en una presentación independiente.</p></div><button type="button" className="icon-btn" aria-label="Cerrar" onClick={onClose}><X size={18}/></button></div>
      <div className="fraction-source"><div><small>Producto original</small><strong>{productDisplayName(product)}</strong><span>{product.presentation} · Existencia: {product.stock}</span></div><div><small>Costo por empaque</small><strong>{money(product.cost)}</strong></div></div>
      <div className="fraction-form-grid">
        <label>Empaques a fraccionar<input type="number" min="1" max={product.stock} step="1" value={packageQuantity} onChange={e=>setPackageQuantity(e.target.value)}/><small>Disponible: {product.stock}</small></label>
        <label>Contenido por empaque<input type="number" min="1" step="1" value={unitsPerPackage} onChange={e=>setUnitsPerPackage(e.target.value)}/><small>Unidades mínimas por caja, frasco o paquete</small></label>
        <label>Unidad mínima<input value={baseUnitName} onChange={e=>setBaseUnitName(e.target.value)} placeholder="Tableta, cápsula, ml..."/></label>
        <label>Presentación que se creará<input value={presentationName} onChange={e=>setPresentationName(e.target.value)} placeholder="Blíster, unidad, paquete..."/></label>
        <label>Unidades por presentación<input type="number" min="1" step="1" value={unitsPerPresentation} onChange={e=>setUnitsPerPresentation(e.target.value)}/></label>
      </div>
      <div className="fraction-preview"><div><small>Se descontarán del original</small><strong>{Number.isFinite(packages)&&packages>0?packages:0} empaque(s)</strong></div><div><small>Se crearán</small><strong>{Number.isInteger(output)&&output>0?output:0} {presentationName.trim()||'presentación'}(es)</strong></div><div><small>Costo por nueva presentación</small><strong>{money(Number.isFinite(unitCost)?unitCost:0)}</strong></div></div>
      <p className="fraction-price-note">Precios sugeridos calculados con los márgenes configurados: 40% minorista y 20% mayorista. El producto fraccionado quedará vinculado al original.</p>
      {error&&<p className="form-error" role="alert">{error}</p>}
      <div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button type="button" className="primary" disabled={!canConfirm} onClick={submit}><Package size={15}/> Confirmar fraccionamiento</button></div>
    </section>
  </div>;
}

function InventoryProductDetails({product,onClose,onEdit,onPrintLabel}:{product:Product;onClose:()=>void;onEdit:(p:Product)=>void;onPrintLabel:(p:Product)=>void}) {
  const status = product.stock <= 0 ? 'Agotado' : product.stock <= product.minStock ? 'Stock bajo' : 'En stock';
  const expiry = product.expiry ? new Date(product.expiry+'T00:00:00').toLocaleDateString('es-HN') : 'No registrado';
  const ingredients = product.activeIngredientDetails?.length ? product.activeIngredientDetails : (product.activeIngredients ?? []).map(name=>({name,strength:'',unit:''}));
  const row = (label:string,value:string|number|undefined) => <div className="inventory-detail-row" key={label}><span>{label}</span><strong>{value===undefined||value===''?'No registrado':value}</strong></div>;
  return <div className="modal-backdrop inventory-detail-backdrop" role="presentation" onClick={e=>{if(e.target===e.currentTarget)onClose();}}>
    <section className="inventory-detail-modal" role="dialog" aria-modal="true" aria-labelledby="inventory-detail-title">
      <header className="inventory-detail-head"><div><span className="pill">INVENTARIO</span><h2 id="inventory-detail-title">Detalle del producto</h2><p>Consulta la información sin salir del inventario.</p></div><div className="inventory-detail-head-actions"><button className="icon-btn inventory-detail-edit-btn" type="button" title="Editar producto" aria-label={"Editar "+product.name} onClick={()=>{onClose();onEdit(product);}}><Pencil size={15}/></button><button className="icon-btn" type="button" aria-label="Cerrar" onClick={onClose}><X size={18}/></button></div></header>
      <div className="inventory-detail-body">
        <aside className="inventory-detail-summary">
          <div className="inventory-detail-image">{product.imageUrl?<img src={product.imageUrl} alt={productDisplayName(product)}/>:<div className="inventory-detail-no-image"><Package size={42}/><span>Sin imagen registrada</span></div>}</div>
          <div className="inventory-detail-name-row"><h3>{productDisplayName(product)}</h3><span className={product.stock<=product.minStock?'stock low':'stock'}>{status}</span></div>
          <p className="inventory-detail-code"><Barcode size={15}/>{product.code||'Sin código de barras'}</p>
          {ingredients.length>0&&<div className="inventory-detail-ingredients"><h4><Pill size={15}/> Principios activos</h4>{ingredients.map((i,n)=><div key={i.name+'-'+n}>{i.name}{i.strength?' · '+i.strength+' '+i.unit:''}</div>)}</div>}
          {product.drugInfo?.indications&&<div className="inventory-detail-description"><h4>Indicaciones registradas</h4><p>{product.drugInfo.indications}</p></div>}
        </aside>
        <div className="inventory-detail-sections">
          <section className="inventory-detail-section"><h4><Info size={16}/> Información general</h4>{row('Categoría',product.category)}{row('Laboratorio',product.laboratory)}{row('Presentación',product.presentation)}{row('Código',product.code)}</section>
          <section className="inventory-detail-section"><h4><DollarSign size={16}/> Precios y existencias</h4>{row('Costo unitario',money(product.cost))}{row('Precio minorista',money(product.retail))}{row('Margen minorista',margin(product.retail,product.cost).toFixed(1)+'%')}{row('Precio mayorista',money(product.wholesale))}{row('Margen mayorista',margin(product.wholesale,product.cost).toFixed(1)+'%')}{row('Stock actual',product.stock)}{row('Stock mínimo',product.minStock)}{(product.additionalPrices??[]).map(p=>row(p.name,money(p.price)))}</section>
          <section className="inventory-detail-section"><h4><CalendarClock size={16}/> Lote y vencimiento</h4>{row('Lote',product.lot)}{row('Fecha de vencimiento',expiry)}{row('Estado de vencimiento',product.expiry?(daysUntil(product.expiry)<0?'Vencido':daysUntil(product.expiry)+' días restantes'):'No registrado')}</section>
          <section className="inventory-detail-section"><h4><Package size={16}/> Información adicional</h4>{row('Proveedor',product.supplier)}{row('ISV configurado',product.taxEnabled?(product.taxRate??0)+'%':'No aplica / no configurado')}{product.drugInfo?.source&&row('Fuente',product.drugInfo.source)}{product.drugInfo?.reviewStatus&&row('Revisión de ficha',product.drugInfo.reviewStatus)}</section>
          {(product.drugInfo?.dosage||product.drugInfo?.duration||product.drugInfo?.warnings)&&<section className="inventory-detail-section"><h4><Pill size={16}/> Información farmacológica registrada</h4>{product.drugInfo?.dosage&&row('Posología',product.drugInfo.dosage)}{product.drugInfo?.duration&&row('Duración',product.drugInfo.duration)}{product.drugInfo?.warnings&&row('Advertencias',product.drugInfo.warnings)}<p className="inventory-detail-note">Información de referencia guardada en la ficha; verificar la presentación y fuente antes de utilizarla clínicamente.</p></section>}
        </div>
      </div>
      <footer className="inventory-detail-footer"><button className="secondary" type="button" title="Preparar etiqueta de este producto" onClick={()=>onPrintLabel(product)}><Printer size={14}/> Imprimir etiqueta</button><button className="secondary inventory-detail-pharma-btn" type="button" onClick={()=>{const query=[product.name,product.laboratory,product.presentation,(product.activeIngredientDetails??[]).map(i=>i.name+" "+i.strength+" "+i.unit).join(" ")].filter(Boolean).join(" ").trim();window.open("https://www.google.com/search?q="+encodeURIComponent(query+" medicamento ficha técnica principio activo indicaciones advertencias"),"_blank","noopener,noreferrer");}}><Pill size={14}/> Asistente farmacológico</button><button className="secondary" type="button" onClick={onClose}><X size={16}/> Cerrar</button></footer>
    </section>
  </div>;
}

function BarcodeLabel({product}:{product:Product}) {
  const svg=useRef<SVGSVGElement>(null);
  useEffect(()=>{if(svg.current&&product.code){try{JsBarcode(svg.current,product.code,{format:'CODE128',displayValue:true,font:'Arial',fontSize:11,textMargin:2,height:38,margin:3,background:'#ffffff',lineColor:'#111111'});}catch{if(svg.current)svg.current.innerHTML='';}}},[product.code]);
  return <div className="barcode-label"><strong className="label-name">{productDisplayName(product)}</strong><span className="label-presentation">{product.presentation||product.category}</span><svg ref={svg} aria-label={`Código de barras ${product.code}`}/><strong className="label-price">{money(product.retail)}</strong></div>;
}

