  const updatePriceOption=(id:string,field:'name'|'price'|'marginPercent',value:string|number)=>setForm(f=>({...f,additionalPrices:(f.additionalPrices??[]).map(option=>{if(option.id!==id)return option;if(field==='name')return {...option,name:String(value)};if(value==='')return {...option,price:0,marginPercent:0};if(field==='price'){const price=Math.max(0,Number(value)||0);return {...option,price,marginPercent:price>0?Number(((price-f.cost)/price*100).toFixed(2)):0};}const margin=Math.min(99.9,Math.max(-100,Number(value)||0));const price=f.cost/(1-margin/100);return {...option,marginPercent:margin,price:Number.isFinite(price)?Number(price.toFixed(2)):0};})}));
